  // Config field label/description catalog — keyed by the normalized SCHEMA
  // path (see normalizeConfigFieldPath in lib/i18n.ts): a map/list instance
  // key (agent alias, principal id, role id, ...) collapses to `*`, so one
  // entry covers every instance. Absent entries fall back to the field's
  // schema-agnostic humanized label / the Rust `///` doc comment (English) —
  // this catalog is a deliberately partial, high-traffic overlay, not a full
  // translation of the config schema. See check-i18n.mjs's schema-paths
  // audit for orphan/typo detection against the live schema.

  // Top-level core fields
  'config.field.locale.label': 'Язык',
  'config.field.locale.desc': 'Язык интерфейса и локализованных сообщений панели управления.',
  'config.field.schema_version.label': 'Версия схемы',
  'config.field.schema_version.desc': 'Версия схемы конфигурации, используется при миграциях во время обновления. Не редактируется вручную.',

  // gateway.*
  'config.field.gateway.host.label': 'Адрес прослушивания',
  'config.field.gateway.host.desc': 'IP-адрес или имя хоста, на котором шлюз принимает подключения.',
  'config.field.gateway.port.label': 'Порт',
  'config.field.gateway.port.desc': 'TCP-порт основного (внутреннего) листенера шлюза.',
  'config.field.gateway.path_prefix.label': 'Префикс пути',
  'config.field.gateway.path_prefix.desc': 'Префикс URL, добавляемый ко всем маршрутам API и панели управления — нужен, например, при работе за обратным прокси.',
  'config.field.gateway.allow_public_bind.label': 'Разрешить публичный бинд',
  'config.field.gateway.allow_public_bind.desc': 'Разрешает прослушивание на не-loopback адресе (0.0.0.0 и подобных) без явного предупреждения о риске.',
  'config.field.gateway.allow_remote_admin.label': 'Разрешить удаленное администрирование',
  'config.field.gateway.allow_remote_admin.desc': 'Разрешает административные операции (перезапуск, обновление и т. п.) с удаленных, не-loopback подключений.',
  'config.field.gateway.allow_self_upgrade.label': 'Разрешить самообновление',
  'config.field.gateway.allow_self_upgrade.desc': 'Позволяет обновлять ZeroClaw прямо из панели управления — шлюз скачивает и устанавливает новую версию.',
  'config.field.gateway.check_updates.label': 'Проверять обновления',
  'config.field.gateway.check_updates.desc': 'Периодически проверяет наличие новой версии ZeroClaw.',
  'config.field.gateway.idempotency_max_keys.label': 'Максимум ключей идемпотентности',
  'config.field.gateway.idempotency_max_keys.desc': 'Верхняя граница числа одновременно хранимых ключей идемпотентности запросов.',
  'config.field.gateway.idempotency_ttl_secs.label': 'Время жизни ключа идемпотентности (сек)',
  'config.field.gateway.idempotency_ttl_secs.desc': 'Через сколько секунд сохраненный ключ идемпотентности запроса становится недействительным.',
  'config.field.gateway.long_running_request_timeout_secs.label': 'Таймаут долгих запросов (сек)',
  'config.field.gateway.long_running_request_timeout_secs.desc': 'Максимальное время выполнения запроса, помеченного как долгий, например потокового ответа агента.',
  'config.field.gateway.pair_rate_limit_per_minute.label': 'Лимит запросов сопряжения в минуту',
  'config.field.gateway.pair_rate_limit_per_minute.desc': 'Максимальное число попыток сопряжения в минуту с одного источника.',
  'config.field.gateway.paired_tokens.label': 'Сопряженные токены',
  'config.field.gateway.paired_tokens.desc': 'Токены, выпущенные в результате успешного сопряжения устройств.',
  'config.field.gateway.pairing_dashboard.code_length.label': 'Длина кода сопряжения',
  'config.field.gateway.pairing_dashboard.code_length.desc': 'Число цифр в одноразовом коде сопряжения панели управления.',
  'config.field.gateway.pairing_dashboard.code_ttl_secs.label': 'Время жизни кода сопряжения (сек)',
  'config.field.gateway.pairing_dashboard.code_ttl_secs.desc': 'Через сколько секунд неиспользованный код сопряжения истекает.',
  'config.field.gateway.pairing_dashboard.lockout_secs.label': 'Блокировка после неудачных попыток (сек)',
  'config.field.gateway.pairing_dashboard.lockout_secs.desc': 'На сколько секунд блокируется ввод кода после превышения числа неудачных попыток.',
  'config.field.gateway.pairing_dashboard.max_failed_attempts.label': 'Максимум неудачных попыток',
  'config.field.gateway.pairing_dashboard.max_failed_attempts.desc': 'Число неверных попыток ввода кода сопряжения до блокировки.',
  'config.field.gateway.pairing_dashboard.max_pending_codes.label': 'Максимум ожидающих кодов',
  'config.field.gateway.pairing_dashboard.max_pending_codes.desc': 'Максимальное число одновременно действующих неиспользованных кодов сопряжения.',
  'config.field.gateway.public.enabled.label': 'Публичный листенер включен',
