  'config.field.authz.principals.*.profiles.label': 'Роли',
  'config.field.authz.principals.*.profiles.desc': 'Роли (профили доступа), назначенные этому субъекту.',
  'config.field.authz.principals.*.token_hashes.label': 'Хеши токенов',
  'config.field.authz.principals.*.token_hashes.desc': 'Хеши токенов доступа, выданных этому субъекту. Сами токены нигде не хранятся.',
  'config.field.authz.profiles.*.admin.label': 'Администратор',
