  'config.field.runtime_profiles.*.compact_context.label': 'Компактный контекст',
  'config.field.runtime_profiles.*.compact_context.desc': 'Использовать компактную начальную загрузку контекста (6000 символов / 2 фрагмента RAG). Если не задано, наследуется.',
  'config.field.runtime_profiles.*.context_compression.enabled.label': 'Сжатие контекста включено',
  'config.field.runtime_profiles.*.context_compression.enabled.desc': 'Компонент сжатия контекста удален из среды выполнения — включение флага сейчас ни на что не влияет. Значение по умолчанию `false` отражает реальное поведение; явное значение `true` приводит только к предупреждению `context_compression_unsupported`.',
  'config.field.runtime_profiles.*.context_compression.identifier_policy.label': 'Политика сохранения идентификаторов',
  'config.field.runtime_profiles.*.context_compression.identifier_policy.desc': 'Часть механизма сжатия контекста, отключенного в среде выполнения (см. `context_compression.enabled`); сейчас не имеет эффекта.',
