  // transcription.*
  'config.field.transcription.api_key.label': 'API-ключ распознавания',
  'config.field.transcription.api_key.desc': 'API-ключ для запросов распознавания речи (провайдер Groq). Используйте синтаксис переменных окружения по схеме (`ZEROCLAW_transcription__api_key=...`) для внедрения в среде выполнения. Устаревший резервный вариант через `GROQ_API_KEY` удален в v0.8.0.',
  'config.field.transcription.api_url.label': 'URL API распознавания',
