  'config.field.transcription.max_audio_bytes.label': 'Максимальный размер аудио (байт)',
  'config.field.transcription.max_audio_bytes.desc': 'Необязательная глобальная верхняя граница размера аудио в байтах, применяемая до отправки любому провайдеру распознавания. Ограничения конкретного провайдера действуют дополнительно.',
  'config.field.transcription.max_duration_secs.label': 'Максимальная длительность (сек)',
  'config.field.transcription.max_duration_secs.desc': 'Максимальная длительность голосового сообщения в секундах (более длинные сообщения пропускаются).',
