  // a2a.*
  'config.field.a2a.server.bind.label': 'Адрес объявления (advertise)',
  'config.field.a2a.server.bind.desc': 'Необязательное переопределение хоста только для объявления в URL эндпоинтов карточки. Маршруты всегда обслуживаются на собственном листенере шлюза; это меняет только хост, публикуемый в объявленных эндпоинтах, если A2A выставлен на другом адресе. `None` — берется из хоста шлюза.',
