  'config.field.security.leak_detection.sensitivity.desc': 'Чувствительность обнаружения от 0.0 до 1.0; чем выше значение, тем агрессивнее проверка.',
  'config.field.security.nat64_prefixes.label': 'Префиксы NAT64',
  'config.field.security.nat64_prefixes.desc': 'Специфичные для сети префиксы NAT64 (RFC 6052), развернутые в сети этого хоста, например `[security] nat64_prefixes = ["2001:db8:122:344::/96"]`. По умолчанию: `[]`.\n\nТранслятор NAT64 доставляет любой IPv6-адрес назначения из одного из этих префиксов на встроенный в него IPv4-адрес. Префикс выбирается организацией самостоятельно и по самому адресу не определяется, поэтому без этого списка имя хоста, подконтрольное злоумышленнику, может резолвиться в IPv6-адрес, выглядящий глобальным, который локальный транслятор преобразует в `10.0.0.1` или `169.254.169.254` — и проверки на SSRF при исходящих запросах это пропустят. Указание используемых префиксов делает адрес, в который они транслируются, частью границы валидации для инструментов `http_request`, `web_fetch` и `text_browser`.\n\nКаждая запись имеет вид `<ipv6>/<length>`, где length — одна из длин из RFC 6052 §2.2 (32, 40, 48, 56, 64 или 96), и без установленных битов за пределами этой длины. Некорректная запись приводит к ошибке при создании инструментов, читающих этот список, а не просто пропускается, поэтому опечатка не может незаметно сузить границу проверки.\n\nЗначение по умолчанию корректно для развертываний без транслятора NAT64, а также для тех, что используют только общеизвестный префикс `64:ff9b::/96`, который классифицируется без дополнительной настройки.\n\nRFC 8215 также стандартизирует `64:ff9b:1::/48` как локальный блок NAT64, и его тоже необходимо декларировать. Валидатор публичных адресов уже отклоняет весь этот блок как неглобальный, поэтому значение по умолчанию само по себе безопасно. Но именно эту проверку на неглобальность снимает разрешение приватных хостов (`allowed_private_hosts`), а безусловный фильтр метаданных, остающийся под ней, декодирует только общеизвестный префикс `/96`, но не этот блок. Поэтому развертывание, транслирующее из `64:ff9b:1::/48`, обязано декларировать именно этот префикс здесь; иначе после разрешения хоста через `allowed_private_hosts` адрес из этого блока достигнет встроенного в него IPv4-адреса назначения без классификации этого адреса.\n\nОбъявленные префиксы могут пересекаться, и адрес, попадающий в несколько из них, декодируется в *разные* IPv4-адреса назначения для каждого. Проверка консервативна: адрес принимается, только если каждая соответствующая ему декларированная трансляция ведет в допустимое место, поэтому более узкий префикс, декодирующий адрес в приватное назначение или в адрес метаданных, отклонит его, даже если более широкий префикс декодирует тот же адрес как глобальный. Если это отклоняет адреса назначения, которые вы считаете легитимными, сузьте декларированные префиксы до фактически развернутых трансляций.',
