  'config.field.security.otp.cache_valid_secs.label': 'Окно повторного использования OTP (сек.)',
  'config.field.security.otp.cache_valid_secs.desc': 'Окно, в течение которого недавно подтвержденный одноразовый код (OTP) можно использовать повторно.',
  'config.field.security.otp.challenge_max_attempts.label': 'Максимум попыток OTP',
  'config.field.security.otp.challenge_max_attempts.desc': 'Максимальное число попыток ввода OTP-кода до блокировки.',
  'config.field.security.otp.enabled.label': 'OTP-проверка включена',
  'config.field.security.otp.enabled.desc': 'Включает проверку по одноразовому коду (OTP) для чувствительных действий. По умолчанию выключено для обратной совместимости.',
  'config.field.security.otp.gated_actions.label': 'Действия под контролем OTP',
  'config.field.security.otp.gated_actions.desc': 'Названия инструментов/действий, требующих подтверждения по OTP. Пустые или некорректные записи отклоняются при загрузке конфигурации; запись, не соответствующая известному контролируемому действию, принимается, но логируется на уровне WARN, поскольку не может быть применена на практике.',
  'config.field.security.otp.gated_domain_categories.label': 'Категории доменов под контролем OTP',
  'config.field.security.otp.gated_domain_categories.desc': 'Готовые категории доменов, разворачиваемые в список `gated_domains`.',
  'config.field.security.otp.gated_domains.label': 'Домены под контролем OTP',
  'config.field.security.otp.gated_domains.desc': 'Явные шаблоны доменов, требующие подтверждения по OTP.',
  'config.field.security.otp.method.label': 'Метод OTP',
