  'config.field.hardware.transport.label': 'Транспорт',
  'config.field.hardware.transport.desc': 'Способ подключения к оборудованию: native — Linux SBC с прямым GPIO; serial — USB-микроконтроллер через TTY; probe — отладочный пробник SWD/JTAG; none — отключено.',
  'config.field.hardware.workspace_datasheets.label': 'Индексировать даташиты рабочей области',
  'config.field.hardware.workspace_datasheets.desc': 'Индексирует преобразованные .md и .txt даташиты из рабочей области в локальное RAG-хранилище для поиска по распиновкам и характеристикам. PDF не поддерживаются — их нужно предварительно сконвертировать.',
  'config.field.http_request.allow_private_hosts.label': 'Разрешить приватные хосты',
  'config.field.http_request.allow_private_hosts.desc': 'Разрешает запросы к приватным и локальным хостам (RFC 1918, loopback, .local). По умолчанию выключено (защита от SSRF). Адреса метаданных облаков остаются заблокированы независимо от этой настройки.',
  'config.field.http_request.allowed_domains.label': 'Разрешённые домены',
